import sys
from collections import Counter

def input():
	return sys.stdin.readline()[:-1]

def readline():
	return map(int, input().split())
MOD = 10 ** 9 + 7

def main():
	(n, p) = readline()
	a = sorted(readline())
	values = set()
	for ai in a:
		v = ai
		while v not in values:
			r = v % 4
			if r == 2 or v == 0:
				values.add(ai)
				break
			elif r == 0:
				v //= 4
			else:
				v //= 2
	c = Counter(map(int.bit_length, values))
	x = y = 0
	ans = 0
	for i in range(1, p + 1):
		z = (c.get(i, 0) + x + y) % MOD
		ans += z
		(x, y) = (y, z)
	print(ans % MOD)
main()
